import * as React from "react";

export type PauseCircleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function PauseCircleIcon({ size = 20, ...props }: PauseCircleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5" /><path d="M9.8 8.5v7M14.2 8.5v7" />
    </svg>
  );
}
